// More complete local custom-asset forms based on the observed creation flows.
data.customAssets.skillSets??=[];
const deepSubtypes=['Agile','Beast','Beastman','Brute','Champion','Fanatic','Flying','Ganger','Hanger-on','Hybrid','Leader','Loner','Manoeuvrable','Mounted','Ogryn','Pet','Pious','Prospect','Ratling','Skimmer','Specialist','Spyrer','Support','Tracked','Transport (X)','Walker','Wheeled','Wyrd'];
const deepStatKeys=['M','WS','BS','S','T','W','I','A','Sv','Ld','Cl','Wil','Int'];
const deepNames={equipment:'Equipment',fighters:'Fighter',skills:'Skill',gangTypes:'Gang Type',tradingPosts:'Trading Post',collections:'Asset Collection'};
const deepText=(name,label,value='',placeholder='',required=false)=>`<label>${label}<input name="${name}" type="text" value="${esc(value)}" placeholder="${esc(placeholder)}" ${required?'required':''}></label>`;
const deepDescription=a=>`<label class="wide">Description<textarea name="description" maxlength="400" placeholder="Enter description (optional)">${esc(a?.description||'')}</textarea><small>0/400 characters</small></label>`;
function deepAssetFields(kind,a){let common=deepText('name',`${deepNames[kind]} Name *`,a?.name||'',`Enter ${deepNames[kind].toLowerCase()} name`,true);if(kind==='equipment')return common+select('equipmentType','Equipment Type *',['Weapon','Wargear','Armour','Ammunition','Accessory','Other'],a?.equipmentType||'Weapon')+select('category','Category *',['General','Basic','Pistol','Special','Heavy','Melee','Grenade','Armour','Equipment','Other'],a?.category||'General')+deepText('tradePoints','Trade Points *',a?.tradePoints||'','e.g. 2 or E',true)+field('cost','Cost *',a?.cost??0,'number','min="0" required')+`<label class="checkline wide"><input type="checkbox" name="consumable" value="yes" ${a?.consumable==='yes'?'checked':''}> Consumable <small>Can be consumed by the fighter</small></label>`+deepDescription(a);
if(kind==='fighters'){let checks=deepSubtypes.map(x=>`<label class="subtype-choice"><input type="checkbox" name="subtypes" value="${esc(x)}" ${a?.subtypes?.includes(x)?'checked':''}>${esc(x)}</label>`).join('');let statFields=deepStatKeys.map(k=>deepText(`stat_${k}`,`${k}${k==='Sv'?'':' *'}`,a?.stats?.[k]??baseStats[k]??'','','')).join('');return deepText('name','Fighter Type *',a?.name||'','e.g. Subtek or Bully',true)+`<fieldset class="wide"><legend>Fighter Subtype</legend><div class="subtype-grid">${checks}</div></fieldset>`+select('gangType','Gang Type *',[...new Set([...factions,...data.customAssets.gangTypes.map(x=>x.name)])],a?.gangType||factions[0])+field('cost','Cost (credits) *',a?.cost??0,'number','min="0" required')+field('startingXp','Starting XP',a?.startingXp??0,'number','min="0"')+`<div class="wide"><h3>Characteristics</h3><div class="stat-form-grid">${statFields}</div></div>`+textarea('specialRules','Special Rules',a?.specialRules||'')+textarea('skillAccess','Skill Access',a?.skillAccess||'')+textarea('defaultSkills','Default Skills',a?.defaultSkills||'')+textarea('defaultEquipment','Default Equipment',a?.defaultEquipment||'')+`<label class="checkline wide"><input type="checkbox" name="freeSkill" value="yes" ${a?.freeSkill?'checked':''}> Free Skill</label><label class="checkline wide"><input type="checkbox" name="vehicle" value="yes" ${a?.vehicle?'checked':''}> Vehicle</label>`+deepDescription(a)}
if(kind==='skills')return deepText('name','Skill Name *',a?.name||'','Enter skill name',true)+`<label>Skill Set *<select name="skillSet" required><option value="">Select skill set</option>${[...new Set(['Agility','Brawn','Combat','Cunning','Ferocity','Leadership','Savant','Shooting','Tech',...data.customAssets.skillSets])].map(x=>`<option value="${esc(x)}" ${a?.skillSet===x?'selected':''}>${esc(x)}</option>`).join('')}</select></label><div class="wide new-skill-set"><button class="btn small" type="button" data-deep="new-skill-set">New</button><input name="newSkillSet" placeholder="New skill set name" hidden></div>`+deepDescription(a);
if(kind==='gangTypes')return deepText('name','Gang Type Name *',a?.name||'','Enter gang type name',true)+select('alignment','Alignment',['Law Abiding','Outlaw','Neutral'],a?.alignment||'Law Abiding')+deepDescription(a);
if(kind==='tradingPosts'){let items=data.customAssets.equipment.map(e=>`<label class="checkline"><input type="checkbox" name="equipmentIds" value="${e.id}" ${a?.equipmentIds?.includes(e.id)?'checked':''}>${esc(e.name)} · ${fmt(e.cost)} cr</label>`).join('');return common+deepDescription(a)+`<fieldset class="wide"><legend>Equipment</legend><div class="asset-pick-list">${items||'<p class="muted">Create equipment to add it to this post.</p>'}</div></fieldset>`}
let all=[...data.customAssets.equipment.map(x=>['equipment',x]),...data.customAssets.fighters.map(x=>['fighters',x]),...data.customAssets.skills.map(x=>['skills',x]),...data.customAssets.gangTypes.map(x=>['gangTypes',x]),...data.customAssets.tradingPosts.map(x=>['tradingPosts',x])];return common+deepDescription(a)+`<fieldset class="wide"><legend>Items</legend><div class="asset-pick-list">${all.map(([type,x])=>`<label class="checkline"><input type="checkbox" name="items" value="${type}:${x.id}" ${a?.items?.includes(type+':'+x.id)?'checked':''}>${esc(x.name)} <small>${deepNames[type]}</small></label>`).join('')||'<p class="muted">Create assets to add them to this collection.</p>'}</div></fieldset>`}
editAsset=function(a){ensureAssets();let kind=data.assetTab;formModal(`${a?'Edit':'Create Custom'} ${deepNames[kind]}`,deepAssetFields(kind,a),v=>{let form=$('#modal-form'),value={...v};if('cost'in value)value.cost=n(value.cost);if(kind==='equipment')value.consumable=form.querySelector('[name="consumable"]')?.checked?'yes':'no';if(kind==='fighters'){value.subtypes=[...form.querySelectorAll('[name="subtypes"]:checked')].map(x=>x.value);value.stats=Object.fromEntries(deepStatKeys.map(k=>[k,value[`stat_${k}`]]));deepStatKeys.forEach(k=>delete value[`stat_${k}`]);value.startingXp=n(value.startingXp);value.freeSkill=!!form.querySelector('[name="freeSkill"]:checked');value.vehicle=!!form.querySelector('[name="vehicle"]:checked')}if(kind==='skills'){let next=value.newSkillSet?.trim();if(next){if(!data.customAssets.skillSets.includes(next))data.customAssets.skillSets.push(next);value.skillSet=next}delete value.newSkillSet}if(kind==='tradingPosts')value.equipmentIds=[...form.querySelectorAll('[name="equipmentIds"]:checked')].map(x=>x.value);if(kind==='collections')value.items=[...form.querySelectorAll('[name="items"]:checked')].map(x=>x.value);if(a)Object.assign(a,value);else data.customAssets[kind].push({id:id(),...value});save()},`${a?'Save':'Create'} ${deepNames[kind]}`)};
document.addEventListener('click',e=>{let t=e.target.closest('[data-deep]');if(!t)return;let d=t.dataset;if(d.deep==='sell-equipment'||d.deep==='sell-stash'){e.stopImmediatePropagation();let g=gang(),f=g.fighters.find(x=>x.id===d.fighter),list=f?.equipment||g.stash,item=list.find(x=>x.id===d.id);sellItem(g,item,()=>{if(f)f.equipment=f.equipment.filter(x=>x.id!==item.id);else g.stash=g.stash.filter(x=>x.id!==item.id)})}},true);
function resourceDeltaForm(g){let fields='<p class="wide muted">Add or remove resources (e.g. 5 or -5)</p>';let resources=[['credits','Credits'],['reputation','Reputation'],...(g.edition==='N26'?[['tradePoints','Trade Points']]:[])];for(let [key,label] of resources)fields+=`<label>${label} <small>(Current: ${fmt(g[key]||0)})</small><input type="number" name="delta_${key}" placeholder="0" value="0"></label>`;fields+=deepText('reason','Reason (optional)','','Reason (optional)');formModal('Resources',fields,v=>{let changes=[];for(let [key,label] of resources){let delta=Number(v['delta_'+key]||0);if(!Number.isFinite(delta))continue;let old=n(g[key]),next=Math.max(0,old+delta);if(old!==next){g[key]=next;changes.push(`${label}: ${old} → ${next}`)}}if(changes.length){log(g,changes.join(', ')+(v.reason?` · ${v.reason}`:''));save()}},'Save Changes');$('#modal-cancel').textContent='Cancel'}
const xpRows=[];
addXp=function(f){fighterExtra(f);let rows=xpRows.map(([label,points,kind],i)=>`<label class="xp-row wide"><span>${label} <small>(+${points} XP${kind==='count'?' each':''})</small></span>${kind==='count'?`<input type="number" name="count_${i}" value="0" min="0">`:`<input type="checkbox" name="check_${i}" value="yes">`}</label>`).join('');let fields=`<p class="wide muted">Current XP: ${fmt(f.xp)}</p>${rows}<p class="wide" id="xp-total">Total XP: 0</p><label class="wide">XP Amount<input type="number" name="amount" placeholder="XP Amount"></label>${deepText('reason','Reason (optional)','','Reason (optional)')}`;formModal('Add XP',fields,v=>{let amount=v.amount===''?xpRows.reduce((sum,[,points,kind],i)=>sum+points*(kind==='count'?Math.max(0,Number(v[`count_${i}`])||0):v[`check_${i}`]==='yes'?1:0),0):Number(v.amount);if(!Number.isFinite(amount))return false;f.xp=Math.max(0,n(f.xp)+amount);f.xpHistory.unshift({id:id(),at:now(),reason:v.reason||'Battle XP',amount});log(gang(),`${f.name}: ${amount>=0?'+':''}${amount} XP`);save()},'Add XP');$('#modal-form').classList.add('xp-create');$('#modal-cancel').textContent='Cancel'};
document.addEventListener('input',e=>{let form=e.target.closest('.xp-create');if(!form)return;let sum=xpRows.reduce((total,[,points,kind],i)=>total+points*(kind==='count'?Math.max(0,Number(form.querySelector(`[name="count_${i}"]`).value)||0):form.querySelector(`[name="check_${i}"]`).checked?1:0),0);let amount=form.querySelector('[name="amount"]').value;document.querySelector('#xp-total').textContent=`Total XP: ${amount===''?sum:Number(amount)||0}`});
function sellItem(g,item,remove){if(!item)return;formModal('Sell Equipment',`<p data-i18n-ko="합의한 판매 금액을 직접 입력하세요. 공식 판매 규칙은 적용하지 않습니다.">Enter the agreed sale value manually. No official sale rule is applied.</p><p><strong>${esc(item.name)}</strong></p>${field('value','Sale value','','number','min="0" step="1" required')}`,v=>{let amount=Number(v.value);if(!Number.isSafeInteger(amount)||amount<0)return false;remove();g.credits=n(g.credits)+amount;log(g,`${item.name} sold for ${fmt(amount)} credits (manual).`);save()},'Sell')}
const previousStashDeep=stashTab;
stashTab=function(g){return `<section class="card stash-page"><div class="section-heading"><h2>Stash</h2><div class="actions"><button class="btn small" data-action="new-stash">Add</button><button class="btn small" data-play="trade">Trading Post</button></div></div><div class="table-wrap"><table><thead><tr><th>Name</th><th>Cost</th><th>Action</th></tr></thead><tbody>${g.stash.map(e=>{const profiles=window.FighterParity?.stashProfiles?.(e,g.edition)||'';return `<tr class="fp-stash-item" data-stash-item-id="${esc(e.id)}"><td>${esc(e.name)}</td><td>${fmt(e.cost)}</td><td><div class="fp-stash-actions"><button class="btn small" data-stash-assign="${esc(e.id)}">Assign</button><button class="btn small" data-deep="sell-stash" data-id="${esc(e.id)}">Sell</button></div></td></tr>${profiles?`<tr class="fp-stash-profiles" data-stash-profile-id="${esc(e.id)}"><td colspan="3">${profiles}</td></tr>`:''}`}).join('')||'<tr><td colspan="3">Stash is empty.</td></tr>'}</tbody></table></div></section>`};
tradeModal=function(){let g=gang();ensureAssets();let postOptions=[['all','General Trading Post'],...data.customAssets.tradingPosts.map(p=>[p.id,p.name])];let list=data.customAssets.equipment;let rows=list.map(a=>`<div class="mini-row trade-item" data-name="${esc(a.name.toLowerCase())}" data-posts="${esc(data.customAssets.tradingPosts.filter(p=>p.equipmentIds?.includes(a.id)).map(p=>p.id).join(' '))}" data-cost="${n(a.cost)}" data-points="${n(a.tradePoints)}"><span><strong>${esc(a.name)}</strong><br><small>${esc(a.category||a.equipmentType||'Equipment')} · ${fmt(a.cost)} cr${a.tradePoints?` · ${esc(a.tradePoints)} Trade Points`:''}</small></span><button class="btn small" data-play="buy-equipment" data-id="${a.id}" ${n(a.cost)>n(g.credits)?'disabled':''}>Buy</button></div>`).join('');showModal('Trading Post',`<div class="trade-controls"><label>Trading Post<select id="trade-post">${postOptions.map(([id,label])=>`<option value="${id}">${esc(label)}</option>`).join('')}</select></label><label class="checkline"><input type="checkbox" id="trade-unrestricted" checked> Unrestricted</label><label>Sort by<select id="trade-sort"><option value="name">Name</option><option value="cost">Cost</option><option value="points">Trade Points</option></select></label><input class="field" id="trade-search" placeholder="Search equipment..."></div><div id="trade-list" class="mini-list">${rows||'<p>No custom equipment. Create equipment in Custom Assets.</p>'}</div>`,'Close',()=>true)};
function filterTrade(){let search=($('#trade-search')?.value||'').toLowerCase(),post=$('#trade-post')?.value||'all',unrestricted=$('#trade-unrestricted')?.checked,sort=$('#trade-sort')?.value;let list=$('#trade-list');if(!list)return;let rows=[...list.querySelectorAll('.trade-item')];rows.forEach(row=>row.hidden=!(window.UKI18n?UKI18n.matches(row.dataset.name,search):row.dataset.name.includes(search))||(post!=='all'&&!row.dataset.posts.split(' ').includes(post)&&!unrestricted));rows.sort((a,b)=>sort==='cost'?Number(a.dataset.cost)-Number(b.dataset.cost):sort==='points'?Number(a.dataset.points)-Number(b.dataset.points):a.dataset.name.localeCompare(b.dataset.name));rows.forEach(row=>list.append(row))}
for(let type of ['input','change'])document.addEventListener(type,e=>{if(e.target.matches('#trade-search,#trade-post,#trade-unrestricted,#trade-sort'))filterTrade()});
document.addEventListener('click',e=>{let t=e.target.closest('[data-deep]');if(!t)return;let d=t.dataset;if(d.deep==='sell-equipment'||d.deep==='sell-stash'){e.stopImmediatePropagation();let g=gang(),f=g.fighters.find(x=>x.id===d.fighter),list=f?.equipment||g.stash,item=list.find(x=>x.id===d.id);sellItem(g,item,()=>{if(f)f.equipment=f.equipment.filter(x=>x.id!==item.id);else g.stash=g.stash.filter(x=>x.id!==item.id)})}},true);
function openChallengeRound(c){let count=c.members.length;formModal('Open Challenge Round',`<p class="wide muted">Every gang in the campaign gets a challenge to issue.</p><label class="wide">Cycle<input name="cycle" type="number" min="1" placeholder="Enter cycle number (optional)"></label><p class="wide muted">${count?`This creates ${count} challenge${count===1?'':'s'}, one per gang.`:'There are no accepted gangs in this campaign yet.'}</p>`,v=>{if(!count){alert('Add a gang to the campaign first.');return false}let cycle=v.cycle?Number(v.cycle):'';if(cycle&&cycle<1)return false;c.sessions??=[];for(let m of c.members)c.sessions.push({id:id(),scenario:'Challenge',date:new Date().toISOString().slice(0,10),cycle,opponent:'',deployment:'',objective:'',crew:'',notes:'',status:'Active',challenger:m.gangId,winner:'',result:''});save()},'Open Round');$('#modal-cancel').textContent='Cancel'}
function mapEditor(c){c.map??={name:'Campaign Map',background:'#252126',image:''};formModal(c.map?.saved?'Edit Map':'Create Map',deepText('name','Map Name *',c.map.name||'Campaign Map','Enter map name',true)+`<label>Background Color<input type="color" name="background" value="${esc(c.map.background||'#252126')}"></label><label class="wide">Map Image<input type="file" id="map-image-file" accept="image/png,image/jpeg,image/webp"><small>PNG, JPEG or WebP, up to 800 KB</small></label>`,v=>{c.map.name=v.name;c.map.background=v.background;c.map.saved=true;save()},c.map.saved?'Save Map':'Create Map');$('#map-image-file').addEventListener('change',e=>{let file=e.target.files[0];if(!file)return;if(file.size>800000){alert('Choose an image smaller than 800 KB.');e.target.value='';return}let reader=new FileReader();reader.onload=()=>{c.map.image=reader.result;save()};reader.readAsDataURL(file)})}
mapTab=function(c){campaignExtras(c);let m=c.map||{},image=typeof m.image==='string'&&/^data:image\/(png|jpeg|webp);base64,/.test(m.image)?`url("${m.image}")`:'';let dots=c.territories.map((t,i)=>`<button class="map-dot" style="left:${Math.min(95,Math.max(5,Number(t.x??(18+i*21)%90)))}%;top:${Math.min(90,Math.max(10,Number(t.y??(23+i*17)%80)))}%" data-ext="map-edit" data-id="${t.id}" title="${esc(t.name)}"><span>⬡</span><small>${esc(t.name)}</small></button>`).join('');return `<section class="card map-page"><div class="section-heading"><h2>Map</h2><button class="btn small" data-deep="map-editor">${m.saved?'Edit':'Create'}</button></div>${m.saved?`<h3>${esc(m.name)}</h3>`:''}<div class="map-board" style="background-color:${/^#[0-9a-fA-F]{6}$/.test(m.background||'')?m.background:'#252126'};${image?`background-image:${image};background-size:cover;`:''}">${dots||'<div class="map-empty">Add territories to place them on the map.</div>'}</div><div class="actions"><button class="btn small" data-action="new-territory">Add Territory</button></div></section>`};
document.addEventListener('click',e=>{let t=e.target.closest('[data-deep="map-editor"]');if(!t)return;e.stopImmediatePropagation();mapEditor(campaign())},true);
